package Acme::Files::Reader;
use strict;
use warnings;

sub new {
    my ($class, %args) = @_;
    return bless { root => $args{root} }, $class;
}

sub list_files {
    my ($self) = @_;
    opendir(my $dh, $self->{root}) or return ();
    return grep { !/^\./ } readdir $dh;
}

sub read_file {
    my ($self, $name) = @_;
    open(my $fh, "$self->{root}/$name") or die "cannot open $name: $!";
    local $/;
    return <$fh>;
}

1;
